int main(void){uint64_t initial;__asm__ volatile("mrs %0,DIT":"=r"(initial));int feature=0;size_t size=sizeof(feature);if(sysctlbyname("hw.optional.arm.FEAT_DIT",&feature,&size,NULL,0)||feature!=1)return 2;uint64_t inputs[]={0,1,0xffffff,0x1000000,0x1000001,0x1ffffff,0x2000000,0x8000000000000000ULL,UINT64_MAX};printf("{\"initial_main\":%llu,\"feature\":%d,\"cases\":[",initial,feature);unsigned count=0;for(unsigned f=0;f<16;f++){uint64_t flags=(uint64_t)f<<28;for(unsigned i=0;i<sizeof(inputs)/sizeof(inputs[0]);i++){struct result r=regwrite(inputs[i],flags);printf("%s{\"operation\":\"register\",\"input\":%llu,\"input_nzcv\":%llu,\"output\":%llu,\"output_nzcv\":%llu}",count++?",":"",inputs[i],flags,r.value,r.flags);}for(unsigned i=0;i<2;i++){struct result r=immediate(i,flags);printf(",{\"operation\":\"immediate\",\"input\":%u,\"input_nzcv\":%llu,\"output\":%llu,\"output_nzcv\":%llu}",i,flags,r.value,r.flags);count++;}for(unsigned i=0;i<3;i++){immediate(1,flags);struct result r=special(i,flags);printf(",{\"operation\":\"%s\",\"input\":16777216,\"input_nzcv\":%llu,\"output\":%llu,\"output_nzcv\":%llu}",i==0?"write-xzr":i==1?"read-xzr":"sb",flags,r.value,r.flags);count++;}}struct result restored=regwrite(initial,0x50000000);printf("],\"restored\":%llu,\"count\":%u}\n",restored.value,count);return restored.value!=initial;}
